    border-radius: 16px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
    max-width: 600px;
    width: 100%;
    overflow: hidden;
}

.quiz-header {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    padding: 40px 30px;
    text-align: center;
}

.quiz-header h1 {
    font-size: 28px;
    margin-bottom: 8px;
    font-weight: 700;
}

.subtitle {
    font-size: 14px;
    opacity: 0.9;
    font-weight: 400;
}

.quiz-form {
    padding: 40px 30px;
}

.form-field {
    margin-bottom: 32px;
}

.form-field:last-of-type {
    margin-bottom: 24px;
}

.question-card {
    background: #f8f9fa;
    border-radius: 12px;
    padding: 24px;
    border: 2px solid transparent;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.question-card:hover {
    border-color: #667eea;
    box-shadow: 0 4px 12px rgba(102, 126, 234, 0.1);
}

.question-header {
    margin-bottom: 16px;
}

.question-title {
    font-size: 12px;
    font-weight: 600;
    color: #667eea;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.question-card h3 {
    font-size: 16px;
    color: #2c3e50;
    font-weight: 600;
    line-height: 1.4;
}

.help-text {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    background: #e8eaf6;
    border-left: 4px solid #667eea;
    padding: 12px 14px;
    border-radius: 6px;
    margin-bottom: 16px;
    font-size: 13px;
    color: #3f3f7a;
}

.help-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    background: #667eea;
    color: white;
    border-radius: 50%;
    flex-shrink: 0;
    font-size: 11px;
    font-weight: 700;
}

.options-group {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.option {
    display: flex;
    align-items: center;
    padding: 12px 14px;
    background: white;
    border: 2px solid #e0e0e0;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s ease;
    position: relative;
}

.option:hover {
    background: #f0f4ff;
    border-color: #667eea;
}

.option input[type="checkbox"] {
    position: absolute;
    opacity: 0;
    cursor: pointer;
}

.option input[type="checkbox"]:checked ~ .checkmark {
    background: #667eea;
    border-color: #667eea;
}

.option input[type="checkbox"]:checked ~ .checkmark:after {
    display: block;
}

.option input[type="checkbox"]:checked ~ .option-text {
    color: #667eea;
    font-weight: 600;
}

.checkmark {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    border: 2px solid #d0d0d0;
    border-radius: 4px;
    margin-right: 12px;
    flex-shrink: 0;
    transition: all 0.2s ease;
}

.checkmark:after {
    content: "✓";
    color: white;
    font-size: 12px;
    font-weight: 700;
    display: none;
}

.option-text {
    font-size: 14px;
    color: #2c3e50;
    font-weight: 500;
    transition: all 0.2s ease;
}

.submit-btn {
    width: 100%;
    padding: 14px 24px;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 16px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
    box-shadow: 0 4px 15px rgba(102, 126, 234, 0.3);
}

.submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(102, 126, 234, 0.4);
}

.submit-btn:active {
    transform: translateY(0);
}

.result-container {
    padding: 40px 30px;
    text-align: center;
}

.result-container h2 {
    color: #667eea;
    font-size: 24px;
    margin-bottom: 24px;
}

#resultContent {
    text-align: left;
    margin-bottom: 24px;
    background: #f8f9fa;
    padding: 20px;
    border-radius: 8px;
}

.result-question {
    margin-bottom: 20px;
    padding-bottom: 20px;
    border-bottom: 1px solid #e0e0e0;
}

.result-question:last-child {
    border-bottom: none;
    margin-bottom: 0;
    padding-bottom: 0;
}

.result-question h4 {
    color: #2c3e50;
    font-size: 14px;
    margin-bottom: 8px;
}

.result-answer {
    font-size: 13px;
    color: #555;
    padding: 4px 0;
}

.result-answer.correct {
    color: #27ae60;
    font-weight: 600;
}

.result-answer.incorrect {
    color: #e74c3c;
}

.reset-btn {
    padding: 12px 28px;
    background: #667eea;
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.3s ease;
}

.reset-btn:hover {
    background: #764ba2;
    transform: translateY(-2px);
}

@media (max-width: 600px) {
    .quiz-header {
        padding: 30px 20px;
    }

    .quiz-header h1 {
        font-size: 24px;
    }

    .quiz-form {
        padding: 24px 20px;
    }

    .question-card {
        padding: 18px;
    }

    .question-card h3 {
        font-size: 15px;
    }

    .submit-btn {
        padding: 12px 20px;
        font-size: 15px;
    }
}
